package com.lifeos.expenses;import com.lifeos.shared.AuditableEntity;import com.lifeos.users.User;import jakarta.persistence.*;import java.math.*;import java.time.*;@Entity@Table(name="expenses")public class Expense extends AuditableEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=500)private String description;@Column(nullable=false,precision=19,scale=2)private BigDecimal amount;@Enumerated(EnumType.STRING)@Column(nullable=false)private ExpenseCategory category;@Column(nullable=false)private LocalDate expenseDate;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;public Long getId(){return id;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public ExpenseCategory getCategory(){return category;}public void setCategory(ExpenseCategory v){category=v;}public LocalDate getExpenseDate(){return expenseDate;}public void setExpenseDate(LocalDate v){expenseDate=v;}public void setUser(User v){user=v;}}
